DBL={"get","put","run","prep","plan","set","chop","mop","stop","jog","swim","shop","pop","pat","tip","reset","ship","submit","top","transfer","trim","cancel","label"}
def ing(vp):
    w,_,rest=vp.partition(" ")
    if w in DBL: g=w+w[-1]+"ing"
    elif w.endswith("ie"): g=w[:-2]+"ying"
    elif w.endswith("e") and not w.endswith(("ee","ye","oe")) and w!="be": g=w[:-1]+"ing"
    else: g=w+"ing"
    return g+(" "+rest if rest else "")
