assert list(F)==CATS, set(CATS)^set(F)
assert all(len(v)==20 for v in F.values())
PRE=["","","","","","","","","","","","","um, ","uh, ","er, ","so, ","okay so ","right, ","well, ","hey Jarvis, ","Jarvis, ","ok Jarvis, ","yo Jarvis, ","sorry, ","oh, ","actually, ","by the way, ","one more thing, ","while you're at it, ","quick one, ","hang on, ","right so ","erm, so ","hey, quick thing, ","hi, ","hiya, ","morning Jarvis, ","evening Jarvis, ","mate, ","before I forget, ","alright, ","oh and ","also, ","okay, ","Jarvis mate, "]
IND=["","","","","","","","","could you ","can you ","do me a favour and ","I'd like you to ","I need you to ","I want you to ","please ","would you ","any chance you could ","I was hoping you could ","can you please ","could you just ","please can you "]
SUF=["","","","","","","","","",", thanks",", cheers"," please",", ta"," if that's ok"," when you get a sec",", that'd be great"," mate"," thanks"," 👍"," 🙏"," 😊"," please Jarvis",", no rush"," when you can",", thank you"," for me"," 🙂",", cheers Jarvis"]
FILL=["um","uh","like","erm","you know"]
def fillx(r,t):
    a,b=r.choice(CONV); t=t.replace("{ua}",a).replace("{ub}",b)
    return re.sub(r"\{(\w+)\}",lambda m:r.choice(X.get(m.group(1)) or S[m.group(1)]),t)
def genk(k,seed,seen):
    r=random.Random(seed); out=[]; lab=[]
    k0=k; k=k%10   # rounds 10+ (sets 201+) reuse the frame slices with fresh seeds, so the sentences are new
    FR={c:[f for i,f in enumerate(F[c]) if i%10==k] for c in CATS}
    PR=[p for i,p in enumerate(PRE) if i%3==k%3 or p==""]
    IN=[p for i,p in enumerate(IND) if i%2==k%2 or p==""]
    SU=[p for i,p in enumerate(SUF) if i%3==(k//3)%3 or p==""]
    while len(out)<N:
        if k0 and r.random()<.04:   # venting: no command wrappers, people write these lower-case and unpunctuated a lot
            m,vc=make(r,k); x=r.random()
            if x<.3: m=re.sub(r"[,.!?:]","",m).lower()
            elif x<.55: m=m.lower()
            elif x<.9: m=m[0].upper()+m[1:]
            if r.random()<.03:
                i=r.randrange(1,len(m)-2)
                if m[i].isalpha() and m[i+1].isalpha(): m=m[:i]+m[i+1]+m[i]+m[i+2:]
            h=hash(m)
            if h in seen: continue
            seen.add(h); out.append(m); lab.append(len(CATS)+(vc=="crisis")); continue
        c=r.choices(CATS,W)[0]; t=r.choice(FR[c]); imp=t[0]=="!"; q=t[-1]=="?"
        m=fillx(r,t.strip("!?")); pre=r.choice(PR)
        if imp:
            ind=r.choice(IN)
            if ind.startswith("please") and r.random()<.5: ind=""
            m=ind+m
        if r.random()<.1:   # a filler at a natural pause: after "to", "you", "and"
            w=m.split(" "); js=[j for j in range(1,len(w)-1) if w[j-1].lower() in("to","and") and "{" not in w[j]]
            if js: j=r.choice(js); w.insert(j,r.choice(FILL)+","); w[j-1]+=","; m=" ".join(w)
        su=r.choice(SU) if c!='smalltalk' or r.random()<.3 else ""
        if "please" in su and ("please" in m or not (imp or q)): su=""
        if q and r.random()<.6: m+="?"; su=su.lstrip(",")
        m=pre+m+su
        if not q and r.random()<.2 and m[-1].isalpha(): m+=r.choice([".","!","."])
        x=r.random()
        if x<.18: m=re.sub(r"[,.!?:]","",m).lower()
        elif x<.6: m=m[0].upper()+m[1:]
        if r.random()<.03 and len(m)>6:
            i=r.randrange(1,len(m)-2)
            if m[i].isalpha() and m[i+1].isalpha(): m=m[:i]+m[i+1]+m[i]+m[i+2:]
        h=hash(m)
        if h in seen: continue
        seen.add(h); out.append(m); lab.append(CATS.index(c))
    return out,lab
if __name__=="__main__":
    k=int(sys.argv[1]); seen=set()
    for n in range(101+10*k,111+10*k):
        d,l=genk(k,90000+n,seen)
        with open(f"{HERE}jarvis_messages_{n}.md","w") as f:
            f.write(f"# Jarvis Real-Speech Messages, Set {n}\n\n1,000,000 messages, speech round {k+1}. Labels in .labels sidecar.\n\n")
            f.writelines(f"{i}. {m}\n" for i,m in enumerate(d,1))
        open(f"{HERE}jarvis_messages_{n}.labels","w").write("\n".join(map(str,l))+"\n")
        print(n,flush=True)
